import { AppError } from '@crew/shared';
import { getIssue, emitIssue } from './issues.js';
import { projectInput, workflowInput, DEFAULT_WORKFLOW } from '../../../../shared/src/schemas/project.js';
export function publicStatus(row) {
  return { id: row.id, projectId: row.project_id, name: row.name, category: row.category, position: row.position };
}
export function statusesFor(db, projectId) {
  return db.prepare('SELECT * FROM project_statuses WHERE project_id=? ORDER BY position,id').all(projectId).map(publicStatus);
}
export function publicProject(db, row) {
  return {
    id: row.id,
    orgId: row.org_id,
    key: row.key,
    name: row.name,
    description: row.description,
    archived: Boolean(row.archived),
    nextIssueNumber: row.next_issue_number,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    statuses: statusesFor(db, row.id)
  };
}
export function registerProjects(ctx) {
  const { app, db, requireAuth, permissions } = ctx;
  function row(id) {
    const value = db.prepare('SELECT * FROM projects WHERE id=?').get(id);
    if (!value) throw new AppError('NOT_FOUND', 'Project not found', 404);
    return value;
  }
  function emit(req, project, action, before, after) {
    ctx.bus.emit({
      actorId: req.user.id, orgId: project.org_id, projectId: project.id,
      entityType: 'project', entityId: project.id, action,
      before: before ?? null, after: after ?? null, time: ctx.now()
    });
  }
  function ensureKey(orgId, key, exceptId = '') {
    if (db.prepare('SELECT id FROM projects WHERE org_id=? AND key=? AND id<>?').get(orgId, key, exceptId)) {
      throw new AppError('CONFLICT', 'This organization already has a project with that key', 409);
    }
  }
  function writeWorkflow(projectId, statuses) {
    const current = statusesFor(db, projectId);
    const known = new Set(current.map(status => status.id));
    for (const status of statuses) {
      if (status.id && !known.has(status.id)) throw new AppError('VALIDATION', 'Status does not belong to this project', 422, { statuses: status.id });
    }
    const kept = new Set(statuses.map(status => status.id).filter(Boolean));
    const removed = current.filter(status => !kept.has(status.id));
    const hasIssues = db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name='issues'").get();
    for (const status of removed) {
      if (hasIssues && db.prepare('SELECT 1 FROM issues WHERE status_id=? LIMIT 1').get(status.id)) {
        throw new AppError('CONFLICT', 'Move issues out of a status before removing it', 409, { statusId: status.id });
      }
    }
    db.prepare('UPDATE project_statuses SET position=position+100000 WHERE project_id=?').run(projectId);
    for (const status of removed) db.prepare('DELETE FROM project_statuses WHERE id=?').run(status.id);
    const pendingName = '__pending_' + ctx.id() + '_';
    current.forEach((status, index) => {
      if (kept.has(status.id)) db.prepare('UPDATE project_statuses SET name=? WHERE id=?').run(pendingName + index, status.id);
    });
    statuses.forEach((status, position) => {
      if (status.id) {
        db.prepare('UPDATE project_statuses SET name=?,category=?,position=? WHERE id=?').run(status.name, status.category, position, status.id);
      } else {
        db.prepare('INSERT INTO project_statuses VALUES (?,?,?,?,?)').run(ctx.id(), projectId, status.name, status.category, position);
      }
    });
  }
  function workflowIssueState(projectId) {
    return db.prepare('SELECT id FROM issues WHERE project_id=?').all(projectId).map(row => getIssue(ctx, row.id));
  }
  function emitWorkflowIssues(req, snapshots) {
    for (const before of snapshots) {
      const after = getIssue(ctx, before.id);
      if (before.statusName !== after.statusName || before.statusCategory !== after.statusCategory) {
        emitIssue(ctx, req, 'workflow_updated', before, after);
      }
    }
  }
  function list(req, orgId) {
    permissions.scope(req, 'project:read');
    if (orgId) permissions.assertOrg(req, orgId, 'org:read');
    const rows = orgId
      ? db.prepare('SELECT * FROM projects WHERE org_id=? ORDER BY created_at,id').all(orgId)
      : db.prepare('SELECT p.* FROM projects p JOIN memberships m ON m.org_id=p.org_id WHERE m.user_id=? ORDER BY p.created_at,p.id').all(req.user.id);
    const allowed = rows.filter(project => permissions.canProject(req.user.id, project.id, 'project:read'));
    const visible = allowed.filter(project => req.query.archived === 'all' || Boolean(project.archived) === (req.query.archived === 'true'));
    return ctx.paginate(visible.map(project => publicProject(db, project)), req.query);
  }
  app.get('/api/v1/projects', requireAuth, (req, res) => res.json(list(req, req.query.orgId)));
  app.get('/api/v1/orgs/:orgId/projects', requireAuth, (req, res) => res.json(list(req, req.params.orgId)));
  app.post('/api/v1/orgs/:orgId/projects', requireAuth, (req, res) => {
    const { orgId } = req.params;
    permissions.assertOrg(req, orgId, 'project:manage');
    const input = projectInput(req.body);
    ensureKey(orgId, input.key);
    const id = ctx.id();
    const time = ctx.now();
    const project = ctx.transaction(() => {
      db.prepare('INSERT INTO projects (id,org_id,key,name,description,archived,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)')
        .run(id, orgId, input.key, input.name, input.description, Number(input.archived ?? false), time, time);
      writeWorkflow(id, input.statuses ?? DEFAULT_WORKFLOW);
      return publicProject(db, row(id));
    });
    emit(req, row(id), 'created', null, project);
    res.status(201).json({ project });
  });
  app.get('/api/v1/projects/:projectId', requireAuth, (req, res) => {
    const project = permissions.assertProject(req, req.params.projectId, 'project:read');
    res.json({ project: publicProject(db, project), permissions: {
      manage: permissions.canProject(req.user.id, project.id, 'project:manage'),
      write: permissions.canProject(req.user.id, project.id, 'project:write')
    } });
  });
  app.patch('/api/v1/projects/:projectId', requireAuth, (req, res) => {
    const project = permissions.assertProject(req, req.params.projectId, 'project:manage');
    const input = projectInput(req.body, { partial: true });
    const before = publicProject(db, project);
    const affectedIssues = input.statuses ? workflowIssueState(project.id) : [];
    if (input.key) ensureKey(project.org_id, input.key, project.id);
    if (input.key && input.key !== project.key && project.next_issue_number > 1) {
      throw new AppError('CONFLICT', 'A project key cannot change after an issue has been numbered', 409);
    }
    const after = ctx.transaction(() => {
      db.prepare('UPDATE projects SET key=?,name=?,description=?,archived=?,updated_at=? WHERE id=?').run(
        input.key ?? project.key, input.name ?? project.name, input.description ?? project.description,
        Number(input.archived ?? Boolean(project.archived)), ctx.now(), project.id
      );
      if (input.statuses) writeWorkflow(project.id, input.statuses);
      return publicProject(db, row(project.id));
    });
    emit(req, project, 'updated', before, after);
    emitWorkflowIssues(req, affectedIssues);
    res.json({ project: after });
  });
  app.get('/api/v1/projects/:projectId/workflow', requireAuth, (req, res) => {
    permissions.assertProject(req, req.params.projectId, 'project:read');
    res.json({ statuses: statusesFor(db, req.params.projectId) });
  });
  app.put('/api/v1/projects/:projectId/workflow', requireAuth, (req, res) => {
    const project = permissions.assertProject(req, req.params.projectId, 'project:manage');
    const statuses = workflowInput(req.body);
    const before = publicProject(db, project);
    const affectedIssues = workflowIssueState(project.id);
    const after = ctx.transaction(() => {
      writeWorkflow(project.id, statuses);
      db.prepare('UPDATE projects SET updated_at=? WHERE id=?').run(ctx.now(), project.id);
      return publicProject(db, row(project.id));
    });
    emit(req, project, 'workflow_updated', before, after);
    emitWorkflowIssues(req, affectedIssues);
    res.json({ project: after, statuses: after.statuses });
  });
  app.delete('/api/v1/projects/:projectId', requireAuth, (req, res) => {
    const project = permissions.assertProject(req, req.params.projectId, 'project:manage');
    const before = publicProject(db, project);
    ctx.transaction(() => {
      db.prepare('DELETE FROM project_guests WHERE project_id=?').run(project.id);
      db.prepare('DELETE FROM projects WHERE id=?').run(project.id);
    });
    emit(req, project, 'deleted', before, null);
    res.json({ ok: true });
  });
}

import { test, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { testServer } from './helpers.js';
let server, owner, member, guest, org, project, memberId, guestId;
beforeEach(async () => {
  server = await testServer();
  owner = server.agent(); member = server.agent(); guest = server.agent();
  await owner('POST', '/auth/signup', { name: 'Owner', email: 'owner@project.test', password: 'correct-horse-123' });
  memberId = (await member('POST', '/auth/signup', { name: 'Member', email: 'member@project.test', password: 'correct-horse-123' })).data.user.id;
  guestId = (await guest('POST', '/auth/signup', { name: 'Guest', email: 'guest@project.test', password: 'correct-horse-123' })).data.user.id;
  org = (await owner('POST', '/orgs', { name: 'Planning' })).data.organization;
  await owner('POST', '/orgs/' + org.id + '/members', { userId: memberId, role: 'member' });
  await owner('POST', '/orgs/' + org.id + '/members', { userId: guestId, role: 'guest' });
  const created = await owner('POST', '/orgs/' + org.id + '/projects', { key: 'PL', name: 'Planning', description: 'Plan the work' });
  assert.equal(created.status, 201, JSON.stringify(created.data));
  project = created.data.project;
});
afterEach(async () => { await server.close(); });
test('project creation stores default ordered workflow and metadata', async () => {
  assert.equal(project.key, 'PL'); assert.equal(project.nextIssueNumber, 1);
  assert.deepEqual(project.statuses.map(status => status.category), ['todo', 'active', 'done']);
  const read = await owner('GET', '/projects/' + project.id);
  assert.equal(read.data.project.description, 'Plan the work'); assert.equal(read.data.permissions.manage, true);
});
test('project keys are case-insensitively unique within an organization', async () => {
  const result = await owner('POST', '/orgs/' + org.id + '/projects', { key: 'pl', name: 'Duplicate' });
  assert.equal(result.status, 409);
  const second = (await owner('POST', '/orgs', { name: 'Second' })).data.organization;
  assert.equal((await owner('POST', '/orgs/' + second.id + '/projects', { key: 'PL', name: 'Other org' })).status, 201);
});
test('members read projects but cannot create or update their configuration', async () => {
  assert.equal((await member('GET', '/projects/' + project.id)).status, 200);
  assert.equal((await member('PATCH', '/projects/' + project.id, { name: 'No' })).status, 403);
  assert.equal((await member('POST', '/orgs/' + org.id + '/projects', { key: 'NO', name: 'No' })).status, 403);
});
test('guest project access is filtered before cursor pagination', async () => {
  const visible = (await owner('POST', '/orgs/' + org.id + '/projects', { key: 'VS', name: 'Visible' })).data.project;
  await owner('POST', '/projects/' + visible.id + '/guests', { userId: guestId });
  const result = await guest('GET', '/orgs/' + org.id + '/projects?limit=1');
  assert.equal(result.status, 200); assert.deepEqual(result.data.items.map(row => row.id), [visible.id]); assert.equal(result.data.nextCursor, null);
  assert.equal((await guest('GET', '/projects/' + project.id)).status, 403);
});
test('project patch persists description and archive with explicit restore', async () => {
  assert.equal((await owner('PATCH', '/projects/' + project.id, { name: 'Roadmap', description: 'Next quarter', archived: true })).data.project.archived, true);
  assert.equal((await owner('GET', '/projects')).data.items.length, 0);
  assert.equal((await owner('GET', '/projects?archived=true')).data.items[0].name, 'Roadmap');
  await owner('PATCH', '/projects/' + project.id, { archived: false });
  assert.equal((await owner('GET', '/projects')).data.items[0].description, 'Next quarter');
});
test('workflow replacement preserves identifiers when reordering and renaming', async () => {
  const [todo, active, done] = project.statuses;
  const statuses = [done, todo, { ...active, name: 'In progress' }].map(({ id, name, category }) => ({ id, name, category }));
  const result = await owner('PUT', '/projects/' + project.id + '/workflow', { statuses });
  assert.equal(result.status, 200, JSON.stringify(result.data));
  assert.deepEqual(result.data.statuses.map(row => row.id), [done.id, todo.id, active.id]);
  assert.deepEqual(result.data.statuses.map(row => row.position), [0, 1, 2]);
});
test('workflow validation rejects duplicate names and foreign status IDs atomically', async () => {
  const other = (await owner('POST', '/orgs/' + org.id + '/projects', { key: 'OT', name: 'Other' })).data.project;
  const statuses = [{ id: other.statuses[0].id, name: 'Todo', category: 'todo' }, { name: 'Done', category: 'done' }];
  assert.equal((await owner('PUT', '/projects/' + project.id + '/workflow', { statuses })).status, 422);
  assert.deepEqual((await owner('GET', '/projects/' + project.id + '/workflow')).data.statuses, project.statuses);
});
test('workflow cannot remove a status holding an issue', async () => {
  const created = await owner('POST', '/projects/' + project.id + '/issues', { title: 'Keep status', statusId: project.statuses[0].id });
  assert.equal(created.status, 201, JSON.stringify(created.data));
  const statuses = [{ name: 'Ready', category: 'todo' }, { id: project.statuses[2].id, name: 'Done', category: 'done' }];
  assert.equal((await owner('PUT', '/projects/' + project.id + '/workflow', { statuses })).status, 409);
});
test('numbered project keys cannot be changed accidentally', async () => {
  assert.equal((await owner('POST', '/projects/' + project.id + '/issues', { title: 'Issue' })).status, 201);
  assert.equal((await owner('PATCH', '/projects/' + project.id, { key: 'NEW' })).status, 409);
});
test('project deletion removes guest grants and denies later reads', async () => {
  await owner('POST', '/projects/' + project.id + '/guests', { userId: guestId });
  assert.equal((await owner('DELETE', '/projects/' + project.id)).status, 200);
  assert.equal(server.ctx.db.prepare('SELECT count(*) AS n FROM project_guests WHERE project_id=?').get(project.id).n, 0);
  assert.equal((await owner('GET', '/projects/' + project.id)).status, 404);
});
test('project mutation emits complete before and after event summaries', async () => {
  const events = []; server.ctx.bus.subscribe(event => events.push(event));
  await owner('PATCH', '/projects/' + project.id, { name: 'New name' });
  const event = events.find(event => event.entityType === 'project');
  assert.equal(event.orgId, org.id); assert.equal(event.projectId, project.id); assert(event.actorId && event.time);
  assert.equal(event.before.name, 'Planning'); assert.equal(event.after.name, 'New name'); assert.equal(event.after.statuses.length, 3);
});
test('workflow category changes emit hydrated issue events and update sprint remaining work', async () => {
  const issue = (await owner('POST', '/projects/' + project.id + '/issues', { title: 'Workflow issue', statusId: project.statuses[1].id, estimate: 5 })).data.issue;
  const today = new Date().toISOString().slice(0, 10);
  const sprint = (await owner('POST', '/projects/' + project.id + '/sprints', { name: 'Workflow sprint', startDate: today, endDate: today })).data.sprint;
  await owner('POST', '/sprints/' + sprint.id + '/issues', { issueIds: [issue.id] });
  const events = []; server.ctx.bus.subscribe(event => events.push(event));
  const statuses = project.statuses.map(({ id, name, category }) => ({ id, name, category: id === project.statuses[1].id ? 'done' : category }));
  assert.equal((await owner('PUT', '/projects/' + project.id + '/workflow', { statuses })).status, 200);
  assert.equal((await owner('GET', '/sprints/' + sprint.id)).data.sprint.remainingPoints, 0);
  const event = events.find(event => event.entityType === 'issue' && event.action === 'workflow_updated');
  assert.equal(event.before.statusCategory, 'active'); assert.equal(event.after.statusCategory, 'done');
});
test('project validation uses stable 422 details and malformed cursor is rejected', async () => {
  const result = await owner('PATCH', '/projects/' + project.id, { archived: 'yes' });
  assert.equal(result.status, 422); assert(result.data.error.details.archived);
  assert.equal((await owner('GET', '/projects?cursor=invalid')).status, 422);
});
